const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Black Sea brightness comparison: 2022-05-20 vs 2022-06-20
  // Strategy:
  // - Use Sentinel-2 L2A (COPERNICUS/S2_SR) with QA60 and SCL=6 (water) masking.
  // - If no images, try Landsat 8/9 L2 SR with QA_PIXEL mask and JRC water mask.
  // - Expand date windows progressively if empty: ±1, ±3, ±7, ±14 days.
  // - Compute luminance (0.2126*R + 0.7152*G + 0.0722*B) over water at 3 km scale.
  // - Validate: collection size, valid pixel count, and mean in [0,1].
  // - Output concise evidence and final tag.

  const eeGet = (obj) => new Promise((resolve, reject) => obj.evaluate(resolve, reject));

  // Geometry: approximate Black Sea bounding box
  const geom = ee.Geometry.Rectangle([27.0, 40.5, 42.5, 47.5], null, false);

  // Precompute JRC water mask for fallback sensors (occurrence > 50%)
  const jrcWater = ee.Image('JRC/GSW1_4/GlobalSurfaceWater').select('occurrence').gt(50).rename('water');

  function s2Prep(img) {
    const qa = img.select('QA60');
    const scl = img.select('SCL');
    const cloudBitMask = 1 << 10; // opaque clouds
    const cirrusBitMask = 1 << 11; // cirrus
    const noCloud = qa.bitwiseAnd(cloudBitMask).eq(0).and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    const water = scl.eq(6);
    const mask = noCloud.and(water);
    const sr = img.select(['B2','B3','B4']).multiply(0.0001).updateMask(mask);
    const luma = sr.expression('0.2126*R + 0.7152*G + 0.0722*B', {
      R: sr.select('B4'), G: sr.select('B3'), B: sr.select('B2')
    }).rename('luma');
    return luma.copyProperties(img, ['system:time_start','CLOUDY_PIXEL_PERCENTAGE','SPACECRAFT_NAME']);
  }

  function lsPrep(img) {
    // Landsat 8/9 Collection 2 L2 SR scale factors: reflectance = DN * 0.0000275 + (-0.2)
    const sr = img.select(['SR_B2','SR_B3','SR_B4']).multiply(0.0000275).add(-0.2);
    const qa = img.select('QA_PIXEL');
    const clear = qa.bitwiseAnd(1 << 1).eq(0) // dilated cloud
      .and(qa.bitwiseAnd(1 << 2).eq(0)) // cirrus
      .and(qa.bitwiseAnd(1 << 3).eq(0)) // cloud
      .and(qa.bitwiseAnd(1 << 4).eq(0)); // cloud shadow
    const waterMask = jrcWater.eq(1);
    const masked = sr.updateMask(clear).updateMask(waterMask);
    const luma = masked.expression('0.2126*R + 0.7152*G + 0.0722*B', {
      R: masked.select('SR_B4'), G: masked.select('SR_B3'), B: masked.select('SR_B2')
    }).rename('luma');
    return luma.copyProperties(img, ['system:time_start','CLOUD_COVER','SPACECRAFT_ID']);
  }

  async function analyzeLuma(img) {
    const reducer = ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true});
    const stats = img.reduceRegion({
      reducer: reducer,
      geometry: geom,
      scale: 3000,
      maxPixels: 1e9,
    });
    const mean = await eeGet(stats.get('luma_mean'));
    const count = await eeGet(stats.get('luma_count'));
    return {mean, count};
  }

  async function getFromS2(dateStr, windowDays) {
    const start = ee.Date(dateStr).advance(-windowDays, 'day');
    const end = ee.Date(dateStr).advance(windowDays + 1, 'day');
    let col = ee.ImageCollection('COPERNICUS/S2_SR')
      .filterBounds(geom)
      .filterDate(start, end)
      .filter(ee.Filter.lte('CLOUDY_PIXEL_PERCENTAGE', 80))
      .sort('CLOUDY_PIXEL_PERCENTAGE');
    const size = await eeGet(col.size());
    if (!size || size === 0) return {size: 0, status: 'EMPTY'};
    const listLen = Math.min(size, 8);
    const list = col.toList(listLen);
    for (let i = 0; i < listLen; i++) {
      const raw = ee.Image(list.get(i));
      const cp = await eeGet(raw.get('CLOUDY_PIXEL_PERCENTAGE'));
      const luma = s2Prep(raw);
      const stats = await analyzeLuma(luma);
      if (stats && stats.count && stats.count > 0 && stats.mean != null && !Number.isNaN(stats.mean)) {
        return {
          size,
          status: 'OK',
          sensor: 'S2',
          cloudProp: 'CLOUDY_PIXEL_PERCENTAGE',
          cloudVal: cp,
          imageTime: await eeGet(raw.date().format('YYYY-MM-dd')),
          windowDays,
          mean: stats.mean,
          count: stats.count
        };
      }
    }
    return {size, status: 'NOVALID'};
  }

  async function getFromLandsat(dateStr, windowDays) {
    const start = ee.Date(dateStr).advance(-windowDays, 'day');
    const end = ee.Date(dateStr).advance(windowDays + 1, 'day');
    let col8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').filterBounds(geom).filterDate(start, end);
    let col9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2').filterBounds(geom).filterDate(start, end);
    let col = col8.merge(col9).filter(ee.Filter.lte('CLOUD_COVER', 80)).sort('CLOUD_COVER');
    const size = await eeGet(col.size());
    if (!size || size === 0) return {size: 0, status: 'EMPTY'};
    const listLen = Math.min(size, 8);
    const list = col.toList(listLen);
    for (let i = 0; i < listLen; i++) {
      const raw = ee.Image(list.get(i));
      const cp = await eeGet(raw.get('CLOUD_COVER'));
      const luma = lsPrep(raw);
      const stats = await analyzeLuma(luma);
      if (stats && stats.count && stats.count > 0 && stats.mean != null && !Number.isNaN(stats.mean)) {
        return {
          size,
          status: 'OK',
          sensor: 'Landsat',
          cloudProp: 'CLOUD_COVER',
          cloudVal: cp,
          imageTime: await eeGet(raw.date().format('YYYY-MM-dd')),
          windowDays,
          mean: stats.mean,
          count: stats.count
        };
      }
    }
    return {size, status: 'NOVALID'};
  }

  async function getBrightness(dateStr) {
    const windows = [1, 3, 7, 14];
    // Try S2 first
    for (const w of windows) {
      const res = await getFromS2(dateStr, w);
      if (res.status === 'OK') return res;
      if (res.status === 'NOVALID') return {status: 'C2', detail: 'S2 images exist but no valid water pixels after masking'};
    }
    // If all S2 windows empty, try Landsat
    let anyEmpty = true;
    for (const w of windows) {
      const res = await getFromLandsat(dateStr, w);
      if (res.status === 'OK') return res;
      if (res.status === 'NOVALID') return {status: 'C2', detail: 'Landsat images exist but no valid water pixels after masking'};
      if (res.size > 0) anyEmpty = false;
    }
    if (anyEmpty) return {status: 'C1', detail: 'No images found for both sensors in all windows'};
    return {status: 'C2', detail: 'Images exist but no valid pixels'};
  }

  try {
    console.log('Region: Black Sea bbox [27.0,40.5,42.5,47.5]');

    const may = await getBrightness('2022-05-20');
    if (may.status !== 'OK') {
      console.log(`2022-05-20: ${may.status} (${may.detail || 'n/a'})`);
      console.log(may.status);
      return;
    }
    console.log(`2022-05-20 ${may.sensor} Images: ${may.size}, Window±${may.windowDays}d, ChosenCloud: ${Math.round((may.cloudVal||0)*10)/10}% (${may.cloudProp}), ImgDate: ${may.imageTime}`);
    console.log(`2022-05-20 ValidPixels: ${may.count}, MeanLuma: ${may.mean !== null ? may.mean.toFixed(4) : 'null'}`);

    // Validate May mean
    if (may.mean == null || Number.isNaN(may.mean) || may.mean < 0 || may.mean > 1) {
      console.log('Calculation invalid for 2022-05-20');
      console.log('C3');
      return;
    }

    const jun = await getBrightness('2022-06-20');
    if (jun.status !== 'OK') {
      console.log(`2022-06-20: ${jun.status} (${jun.detail || 'n/a'})`);
      console.log(jun.status);
      return;
    }
    console.log(`2022-06-20 ${jun.sensor} Images: ${jun.size}, Window±${jun.windowDays}d, ChosenCloud: ${Math.round((jun.cloudVal||0)*10)/10}% (${jun.cloudProp}), ImgDate: ${jun.imageTime}`);
    console.log(`2022-06-20 ValidPixels: ${jun.count}, MeanLuma: ${jun.mean !== null ? jun.mean.toFixed(4) : 'null'}`);

    // Validate Jun mean
    if (jun.mean == null || Number.isNaN(jun.mean) || jun.mean < 0 || jun.mean > 1) {
      console.log('Calculation invalid for 2022-06-20');
      console.log('C3');
      return;
    }

    const diff = jun.mean - may.mean;
    console.log(`Delta(Jun-May): ${diff.toFixed(4)}`);

    // Final decision: increase?
    if (diff > 0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.error('Error:', err && err.message ? err.message : err);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

